@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=Space+Mono:wght@400;700&display=swap');
:root{--ink:#131816;--paper:#e9dfc8;--brass:#c89a55;--rust:#a9573e;--muted:#9c9788;--panel:rgba(17,23,21,.87);--line:rgba(220,190,130,.26)}
*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:#101513;color:var(--paper);font-family:'Barlow Condensed',sans-serif}
button{font:inherit;color:inherit}
#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#111917}
#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.film-grain,.vignette{position:absolute;inset:0;pointer-events:none;z-index:2}
.film-grain{opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.24'/%3E%3C/svg%3E")}
.vignette{background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.24) 100%)}
.screen,.modal-screen{position:absolute;inset:0;z-index:5}
.hidden{display:none!important}
.screen{display:none}
.screen.visible{display:flex}
.screen#title-screen{background:linear-gradient(90deg,rgba(8,13,13,.91) 0%,rgba(8,13,13,.77) 38%,rgba(8,13,13,.06) 100%),linear-gradient(0deg,rgba(8,13,13,.58),transparent 38%);align-items:center}
.title-brand{position:absolute;top:34px;left:5.2%;font-family:'Space Mono',monospace;font-size:12px;letter-spacing:2px;color:#e2d4b8;font-weight:700}
.brand-mark{color:var(--brass);font-size:20px;vertical-align:-2px;margin-right:8px}
.brand-year{font-size:9px;color:#9e9072;margin-left:12px;letter-spacing:1px}
.title-content{margin-left:10.4%;margin-top:5px;max-width:510px}
.eyebrow,.modal-kicker{font-family:'Space Mono',monospace;letter-spacing:2px;font-size:10px;color:#c9a365;font-weight:700}
.title-content h1{font-size:clamp(70px,10vw,130px);line-height:.77;letter-spacing:-3px;margin:20px 0 24px;font-weight:800;color:#f0e8d7;text-shadow:0 4px 28px #080b09}
.title-content h1 span{color:#c99b59}
.title-deck{font-size:19px;color:#c3bda9;letter-spacing:.3px;margin:0 0 32px}
.primary-button{background:#be8b49;border:1px solid #e6bd77;color:#1b201c;font-weight:800;letter-spacing:1.6px;padding:15px 20px;min-width:250px;text-align:left;cursor:pointer;box-shadow:0 5px 25px #0006;transition:.18s}
.primary-button span{float:right;font-size:20px;line-height:15px}
.primary-button:hover{background:#dfad68;transform:translateY(-2px)}
.title-controls{font-family:'Space Mono',monospace;font-size:9px;letter-spacing:1px;color:#d0c6b1;margin-top:30px;display:flex;gap:12px;align-items:center}
.title-controls i{font-style:normal;color:#8f907e;font-size:8px;margin-left:4px}
.title-controls b{color:#99794d}
.title-footer{position:absolute;bottom:26px;left:5.2%;right:5.2%;font-family:'Space Mono',monospace;font-size:9px;letter-spacing:1.4px;color:#837f70;display:flex;justify-content:space-between}
.title-stamp{position:absolute;right:9%;top:14%;border:1px solid #bd7d4a88;color:#cb8954;font:700 11px/1.5 'Space Mono',monospace;letter-spacing:2px;padding:12px 15px;transform:rotate(8deg);opacity:.7;text-align:center}
#hud{position:absolute;inset:0;z-index:4;pointer-events:none}
.topbar{position:absolute;top:0;left:0;right:0;height:67px;padding:0 30px;background:linear-gradient(180deg,rgba(8,13,12,.87),rgba(8,13,12,.4));display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #c9a36525}
.hud-brand{font:700 11px 'Space Mono',monospace;letter-spacing:1.6px;color:#dfd3bc}
.hud-brand>span{font-size:20px;color:var(--brass);vertical-align:-2px;margin-right:8px}
