.live-dot{width:7px;height:7px;border-radius:50%;background:#c96d4d;box-shadow:0 0 9px #ce634a}
#map-toggle{pointer-events:auto;background:none;border:1px solid var(--line);padding:7px 10px;color:#d6c6a9;font:11px 'Space Mono',monospace;cursor:pointer}
