.card-label{font:700 9px 'Space Mono',monospace;letter-spacing:1.2px;color:#b8ad96;display:flex;align-items:center;gap:6px}
.tiny-gear{color:#d7a75e;font-size:15px}
.live-tag{margin-left:auto;color:#79a487;font-size:8px}
.objective-card #objective{font-size:17px;line-height:1.1;margin:10px 0 12px;color:#eee4d0}
.task-meter{height:4px;background:#3a3b31;overflow:hidden}
