#map-inner{height:118px;margin:8px 8px 5px;position:relative;background:linear-gradient(90deg,transparent 32%,#8d765137 33%,#8d765137 35%,transparent 36%,transparent 64%,#8d765137 65%,#8d765137 67%,transparent 68%),linear-gradient(0deg,transparent 32%,#8d765137 33%,#8d765137 35%,transparent 36%,transparent 64%,#8d765137 65%,#8d765137 67%,transparent 68%);border:1px solid #c9a36528}
.map-room{position:absolute;background:#b1946124;border:1px solid #c9a36538}
.map-dot{position:absolute;width:6px;height:6px;margin:-3px;border-radius:50%;background:#83b493;box-shadow:0 0 6px #83b493}
