.keycap,kbd{display:inline-block;border:1px solid #d5c39866;color:#ead6a9;padding:5px 7px;font:9px 'Space Mono',monospace;margin-right:7px;box-shadow:inset 0 -2px #bd9f6228}
.bottom-left .keycap:not(:first-child){margin-left:12px}
