.toast.show{opacity:1;transform:translate(-50%,0)}
.alert-banner{position:absolute;top:72px;left:50%;transform:translateX(-50%);background:#822f26ed;border:1px solid #e17a5b;padding:10px 24px;font:700 12px 'Space Mono',monospace;letter-spacing:2px;box-shadow:0 6px 25px #0008}
.modal-screen{z-index:7;background:rgba(5,9,8,.7);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center}
