.dial-center{position:absolute;inset:33px;border-radius:50%;background:radial-gradient(#9b8256,#443a2b 70%);border:3px solid #c59c5b;display:flex;align-items:center;justify-content:center;color:#e2c787;font:700 11px 'Space Mono',monospace}
.dial-needle{position:absolute;width:3px;height:54px;background:#ead8a6;left:calc(50% - 1.5px);top:13px;transform-origin:50% 59px;filter:drop-shadow(0 0 3px #000)}
.task-side{text-align:center}
.task-side .dial-game{margin:auto}
.task-instruction{font:9px 'Space Mono',monospace;color:#c8b58c;margin-top:12px;text-align:center}
.task-button{margin-top:16px;border:1px solid #cba564;background:#927040;color:#f1dfb8;padding:9px 18px;font:700 10px 'Space Mono',monospace;letter-spacing:1px;cursor:pointer}
.task-button:hover{background:#b18a4d}
.timing-track{width:min(330px,90%);height:18px;border:1px solid #948052;background:#1a211c;position:relative}
.timing-zone{position:absolute;left:40%;width:18%;height:100%;background:#71804c88;border-left:1px solid #9cad6b;border-right:1px solid #9cad6b}
.timing-needle{position:absolute;left:0;top:-5px;height:26px;width:3px;background:#f2d896;box-shadow:0 0 8px #f4d184;transform:translateX(0)}
.switch-row{display:flex;gap:10px}
.switch-tile{width:74px;height:76px;border:1px solid #7e704d;background:#1b211d;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:9px;color:#9f9988;font:9px 'Space Mono',monospace;cursor:pointer}
.switch-tile i{width:18px;height:31px;border:2px solid #92815b;position:relative}
.switch-tile i:after{content:'';position:absolute;width:10px;height:10px;background:#b96b4a;left:2px;top:2px;transition:.12s}
.switch-tile.on i:after{top:15px;background:#95ad70}
.switch-tile.on{color:#d5d3b2;border-color:#95ad70}
.meeting-panel{width:min(650px,calc(100% - 32px))}
.meeting-top{display:flex;justify-content:space-between;align-items:center}
.meeting-panel h2{margin-bottom:5px}
.meeting-panel p{margin:0}
.meeting-top #meeting-timer{font:700 24px 'Space Mono',monospace;color:#d6b879}
.meeting-reason{margin:18px 0 12px;padding:9px 12px;background:#111714;border-left:2px solid #b7794b;color:#bdb29c;font-size:14px}
.vote-options{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.vote-card{background:#252b25;border:1px solid #7c6d4a;padding:10px;text-align:left;cursor:pointer;min-height:65px}
.vote-card:hover{border-color:#d6ac64;background:#38382b}
.vote-card b{display:block;font-size:16px;color:#e2d5bd}
.vote-card small{font:8px 'Space Mono',monospace;color:#99917f}
.vote-card.dead{opacity:.38;cursor:not-allowed}
.vote-result{text-align:center;padding:20px;color:#e0c58d;font-size:19px}
.end-content{margin-left:11%;max-width:530px}
.end-content h2{font-size:75px;line-height:.82;margin:14px 0;color:#e8dfcc}
.end-content h2 span{color:#c99b59}
.end-content p{color:#b4ad99;font-size:17px;margin-bottom:25px}
.end-stats{margin-top:28px;color:#a9a08c;font:9px 'Space Mono',monospace;line-height:2}
.end-stats b{color:#e0c282}
#mobile-controls{position:absolute;inset:auto 0 10px;z-index:6;display:flex;justify-content:space-between;align-items:end;padding:12px;pointer-events:none}
.touch-pad,.touch-actions{pointer-events:auto}
.touch-pad button,.touch-actions button{background:#1b221dc9;border:1px solid #c9a36588;color:#e6d3ac;font:16px 'Space Mono',monospace;border-radius:50%;width:48px;height:48px;touch-action:none}
.touch-pad>button{display:block;margin:auto auto 3px}
.touch-pad div{display:flex;gap:3px}
.touch-pad div button{width:41px;height:41px}
.touch-actions{display:flex;gap:8px}
.touch-actions button{border-radius:4px;width:auto;padding:0 13px;font-size:10px}

@media(max-width:700px){.title-content{margin-left:8%;max-width:75%}
.title-brand{left:7%;font-size:10px}
.title-stamp{right:7%;top:17%;font-size:8px}
.title-controls{flex-wrap:wrap;font-size:8px;gap:7px}
.title-footer{left:7%;right:7%;font-size:7px}
.left-hud{left:10px;top:78px;width:185px}
.objective-card{padding:10px}
.objective-card #objective{font-size:14px}
.crew-card{padding:9px}
.crew-row{font-size:11px;margin-top:6px}
.right-hud{right:10px;top:78px;width:140px}
.mini-map{padding:7px}
.map-inner{height:90px}
#map-inner{height:90px;margin:6px 5px}
.role-chip{padding:7px}
.role-chip small{font-size:6px}
.topbar{height:55px;padding:0 12px}
.hud-brand{font-size:9px}
.hud-brand small{display:none}
.round-clock{font-size:14px}
.round-clock small{display:none}
#map-toggle{padding:5px 7px}
.bottom-hud{height:62px;padding:0 10px}
.bottom-left{display:none}
.bottom-right{margin-left:auto}
.action-button{font-size:8px;padding:8px}
.action-button kbd{display:none}
.interaction-hint{top:-49px}
.modal-panel{padding:24px 20px 16px}
.modal-panel h2{font-size:27px}
.vote-options{grid-template-columns:repeat(2,1fr)}
.end-content{margin-left:8%;margin-right:8%}
.end-content h2{font-size:60px}
.title-deck{font-size:16px}
.primary-button{min-width:220px}
.crew-card .card-label{font-size:8px}
}

@media(max-height:560px){.left-hud{top:71px}
.crew-row:nth-child(n+5){display:none}
.right-hud{top:70px}
.mini-map{padding:5px}
.map-inner,#map-inner{height:78px}
.bottom-hud{height:54px}
.title-content h1{font-size:78px}
.title-content{margin-top:0}
}

