/* Map and touch controls */
.map-station,.map-boiler{display:flex;align-items:center;justify-content:center;text-align:center;color:#d7c294;font:700 5px 'Space Mono',monospace;letter-spacing:-.3px;background:#a98c5635;z-index:1}
.map-boiler{background:#bd94534d;border-color:#d1a85d88;color:#f0d99f;font-size:5px}
.map-corridor{position:absolute;background:#b89a5c55;z-index:0}
#mobile-controls{inset:auto 0 0;align-items:end;min-height:170px;padding:12px 16px calc(14px + env(safe-area-inset-bottom));touch-action:none}
.stick-control{pointer-events:auto;display:flex;flex-direction:column;align-items:center;gap:6px;touch-action:none}
.stick-label,.look-hint{font:700 9px 'Space Mono',monospace;letter-spacing:1.2px;color:#d1bf99;text-shadow:0 2px 6px #000}
.move-stick{width:116px;height:116px;border:1px solid #d5b16b99;border-radius:50%;background:radial-gradient(circle,#242d27d9 0 35%,#171e1bd9 36% 100%);box-shadow:0 5px 20px #0008,inset 0 0 0 8px #d0a45812;position:relative;touch-action:none}
.move-stick:before,.move-stick:after{content:'';position:absolute;background:#d5b16b30}
.move-stick:before{width:1px;left:50%;top:12%;bottom:12%}.move-stick:after{height:1px;top:50%;left:12%;right:12%}
#stick-knob{position:absolute;width:44px;height:44px;left:calc(50% - 22px);top:calc(50% - 22px);border:1px solid #e1c17d;background:radial-gradient(circle at 35% 30%,#bb985a,#675338);border-radius:50%;box-shadow:0 3px 8px #0009;pointer-events:none;will-change:transform}
.touch-actions{display:grid;grid-template-columns:repeat(2,minmax(68px,78px));gap:9px;pointer-events:auto;margin-bottom:4px}
.touch-actions button{width:100%;height:56px;padding:0 7px;border-radius:5px;background:linear-gradient(145deg,#29332cF2,#131a17f2);border:1px solid #d2ad6999;color:#f0ddb8;font:700 10px 'Space Mono',monospace;letter-spacing:.5px;box-shadow:0 4px 14px #0008;touch-action:manipulation;cursor:pointer}
.touch-actions button:first-child{background:linear-gradient(145deg,#80623a,#3a3021);color:#fff0ce}
.touch-actions button:active{transform:translateY(1px);background:#916f3f}
.look-hint{position:absolute;left:50%;bottom:calc(143px + env(safe-area-inset-bottom));transform:translateX(-50%);white-space:nowrap;opacity:.72;pointer-events:none}
#game-canvas{touch-action:none}
@media(max-width:700px){
  #mobile-controls{display:flex;min-height:164px;padding-left:14px;padding-right:14px}
  .left-hud{left:8px;top:64px;width:min(165px,43vw)}
  .right-hud{right:8px;top:64px;width:min(132px,35vw)}
  .objective-card #objective{font-size:13px;margin:7px 0}
  .crew-card{max-height:140px;overflow:hidden}
  .crew-row:nth-child(n+5){display:none}
  .mini-map{padding:6px}.map-title{font-size:8px}#map-inner{height:84px;margin:5px 3px}.map-legend{font-size:6px;gap:3px}
  .role-chip{gap:6px}.role-chip small{font-size:6px;letter-spacing:0}
  .bottom-hud{height:48px;bottom:env(safe-area-inset-bottom);padding:0 10px;justify-content:center;pointer-events:none}
  .bottom-right,.bottom-left{display:none}
  .topbar{padding-top:env(safe-area-inset-top)}
  .interaction-hint{top:58%;font-size:9px}
  .toast{top:calc(50% - 38px);max-width:90%;text-align:center;line-height:1.4}
  .alert-banner{top:calc(58px + env(safe-area-inset-top));width:max-content;max-width:90%;font-size:10px;text-align:center}
  .modal-screen{padding:env(safe-area-inset-top) 0 env(safe-area-inset-bottom);overflow:auto}
  .modal-panel{max-height:calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));overflow-y:auto;padding:22px 18px 14px}
}
@media(max-width:380px){.move-stick{width:100px;height:100px}.touch-actions{grid-template-columns:repeat(2,minmax(62px,70px));gap:7px}.touch-actions button{height:50px;font-size:9px}.left-hud{width:41vw}.right-hud{width:33vw}.map-station,.map-boiler{font-size:4px}}
@media(max-height:560px) and (pointer:coarse){#mobile-controls{min-height:125px;padding-top:5px;padding-bottom:calc(7px + env(safe-area-inset-bottom))}.move-stick{width:82px;height:82px}#stick-knob{width:34px;height:34px;left:calc(50% - 17px);top:calc(50% - 17px)}.look-hint{bottom:calc(103px + env(safe-area-inset-bottom))}.touch-actions button{height:44px}.left-hud,.right-hud{top:60px}.crew-card{display:none}.map-inner,#map-inner{height:68px}}

