    fire('pointerdown', x, y);
    fire('pointermove', x, y - 42);
  }, { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 });
  await page.waitForTimeout(500);
  const moved = await page.evaluate(() => document.querySelector('#map-inner .map-dot.you')?.style.top);
  await page.evaluate(({x,y}) => document.querySelector('#move-stick').dispatchEvent(new PointerEvent('pointerup', { bubbles: true, pointerId: 7, pointerType: 'touch', clientX: x, clientY: y })), {x: rect.x + rect.width / 2, y: rect.y + rect.height / 2});
  if (moved === initial.mapDot) throw new Error(`Joystick did not move player on map (${initial.mapDot} -> ${moved})`);
  // Emergency meeting, vote, round-end, and restart flow.
  await page.locator('#touch-ability').click();
  await page.locator('#meeting-screen').waitFor({ state: 'visible' });
  const voteCount = await page.locator('#vote-options .vote-card').count();
  if (voteCount < 2) throw new Error('Voting options missing');
  await page.locator('#vote-options .vote-card').first().click();
  await page.locator('#end-screen').waitFor({ state: 'visible', timeout: 5000 });
  await page.locator('#restart-button').click();
  await page.waitForTimeout(800);
  const restarted = await page.evaluate(() => ({
    controlsVisible: !document.querySelector('#mobile-controls').classList.contains('hidden'),
    endHidden: document.querySelector('#end-screen').classList.contains('hidden'),
    taskCount: document.querySelector('#task-count').textContent
  }));
  if (!restarted.controlsVisible || !restarted.endHidden || restarted.taskCount !== '0 / 4') throw new Error('Restart failed: ' + JSON.stringify(restarted));
  await page.setViewportSize({ width: 320, height: 640 });
  await page.waitForTimeout(300);
  const narrow = await page.evaluate(() => ({
    width: innerWidth,
    scrollWidth: document.documentElement.scrollWidth,
